VALUES (26803, 'tt0080469', NULL, 'Breaking Glass', 'Breaking Glass', 'movie', 1980, 'https://image.tmdb.org/t/p/w500/4RAp59Kp81uetLN3R7Sai1qcm8D.jpg', 'https://image.tmdb.org/t/p/original/diHub90cz2dNPWFVyQGRmQv09Hs.jpg', 'Breaking Glass is the story of punk singer Kate and her meteoric rise to stardom. Starting out in the rock pubs of London, Kate, assisted by her manager Danny, becomes a huge star overnight. Once at the top the pressure is immense as Kate''s band are squeezed out and she is left to cope alone in the spotlight.', NULL, NULL, 0.95, 6.9, 0, 1.12, '2026-11-25 14:37:42', '2026-11-25 14:37:42')
