VALUES (39276, 'tt0061868', NULL, 'King Kong Escapes', 'キングコングの逆襲', 'movie', 1967, 'https://image.tmdb.org/t/p/w500/1Z2fL5ycdVGs83i4iPdliDZVeVM.jpg', 'https://image.tmdb.org/t/p/original/oAGq2hL4omCXNrtpVBZ9XEoKv8U.jpg', 'An adaptation of the Rankin/Bass cartoon, "The King Kong Show". King Kong is brought in by the evil Dr. Who to dig for Element X in a mine when the robot Mechani-Kong is unable to do the task. This leads to the machine and the real Kong engaging in a tremendous battle atop Tokyo Tower.', NULL, NULL, 2.9984, 6.131, 0, 11.525, '2026-11-25 14:37:42', '2026-11-25 14:37:42')
