VALUES (2612, 'tt0100201', NULL, 'Mr. Destiny', 'Mr. Destiny', 'movie', 1990, 'https://image.tmdb.org/t/p/w500/zlYxDFP9l1YcUnspNzuIa8KVo4N.jpg', 'https://image.tmdb.org/t/p/original/fey7Bj8CULtpAeuF76O17txzJ3z.jpg', 'Larry Burrows is unhappy and feels powerless over his life. He believes his entire life could have turned out differently had he not missed that shot in a baseball game when was a kid. One night he meets this mysterious man, who could change his fate by offering him that alternative life he always dreamed of. But as Burrows embarks on this journey of self discovery he realises that even this new life has its problems and drawbacks..', NULL, NULL, 1.8686, 6.33, 0, 10.01, '2026-11-25 14:37:42', '2026-11-25 14:37:42')
