VALUES (9778, 'tt0240890', NULL, 'Serendipity', 'Serendipity', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/4jS66Qmq2Ru5S2YzHVknGd4xJyT.jpg', 'https://image.tmdb.org/t/p/original/sBecqcXgrLRiwufYr6apGnYA70k.jpg', 'Although already in relationships, two strangers realize they have genuine chemistry after a chance encounter – but part company soon after. Years later, they each yearn to reunite, despite being destined for the altar. But to give true love a chance, they have to find one another again.', NULL, NULL, 6.3974, 6.987, 0, 2.58927272727272708e+01, '2026-07-15 12:01:52', '2026-11-25 14:37:42')
