VALUES (364, 'tt0103776', NULL, 'Batman Returns', 'Batman Returns', 'movie', 1992, 'https://image.tmdb.org/t/p/w500/jKBjeXM7iBBV9UkUcOXx3m7FSHY.jpg', 'https://image.tmdb.org/t/p/original/9vYIWoJ3EoD8UoCiZOCTszrkRVZ.jpg', 'The monstrous Penguin, who dwells in the sewers beneath Gotham, joins up with corrupt mayoral candidate Max Shreck to topple the Batman once and for all. But when Shreck''s timid assistant Selina Kyle finds out, and Shreck tries to kill her, she''s transformed into the sexy Catwoman. She teams up with the Penguin and Shreck to destroy Batman, but sparks fly unexpectedly when she confronts the caped crusader.', NULL, NULL, 9.9162, 6.955, 0, 3.27632142857142838e+01, '2026-07-15 12:01:52', '2026-11-25 14:37:42')
