VALUES (11071, 'tt0047573', NULL, 'Them!', 'Them!', 'movie', 1954, 'https://image.tmdb.org/t/p/w500/tP352STF6BvSROi8K3CMM799TVo.jpg', 'https://image.tmdb.org/t/p/original/bW83NQMHtgFIkDSoZBer4eEnc9V.jpg', 'As a result of nuclear testing, gigantic, ferocious mutant ants appear in the American desert southwest, and a father-daughter team of entomologists join forces with the state police officer who first discovers their existence, an FBI agent and, eventually, the US Army to  eradicate the menace, before it spreads across the continent — and the world.', NULL, NULL, 3.2737, 6.8, 0, 7.90799999999999947e+00, '2026-07-20 01:02:04', '2026-11-25 14:37:42')
