VALUES (10681, 'tt0910970', NULL, 'WALL·E', 'WALL·E', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/hbhFnRzzg6ZDmm8YAmxBnQpQIPh.jpg', 'https://image.tmdb.org/t/p/original/nYs4ZwnJBK4AgljhvzwNz7fpr3E.jpg', 'After hundreds of years doing what he was built for, WALL•E—a robot designed to clean up the earth—discovers a new purpose in life when he meets a sleek search robot named EVE. EVE comes to realize that WALL•E has inadvertently stumbled upon the key to the planet''s future, and races back to space to report to the humans. Meanwhile, WALL•E chases EVE across the galaxy and sets into motion one of the most imaginative adventures ever brought to the big screen.', NULL, NULL, 24.4941, 8.129, 0, 8.55666666666666486e+00, '2026-07-31 03:33:23', '2026-11-25 14:37:42')
