VALUES (43337, 'tt0047114', NULL, 'The Inauguration of the Pleasure Dome', 'The Inauguration of the Pleasure Dome', 'movie', 1954, 'https://image.tmdb.org/t/p/w500/kuVWKVYBu6IFficxSqrOxAAf5c3.jpg', 'https://image.tmdb.org/t/p/original/rpK6roZPro7PHZ29E8hwTWw6CkN.jpg', 'Lord Shiva wakes. A convocation of magicians in the guise of figures from mythology; a masquerade party at which Pan is the prize. The wine of Hecate is poured: Pan''s cup is poisoned by Shiva. Kali blesses the assembly as a bacchic rite ensues.', NULL, NULL, 0.8009, 6.427, 0, 3.05333333333333323e+00, '2026-08-17 16:08:12', '2026-11-25 14:37:42')
